-- PORTABLE-001: lineage fences, durable bounded staging, and local execution grants.
CREATE TABLE portable_state(singleton INTEGER PRIMARY KEY CHECK(singleton=1),lineage TEXT NOT NULL,generation INTEGER NOT NULL DEFAULT 0);
INSERT INTO portable_state VALUES(1,lower(hex(randomblob(16))),0);
CREATE TABLE portable_journal(lineage TEXT NOT NULL,sequence INTEGER NOT NULL,recorded_at TEXT NOT NULL,receipt TEXT NOT NULL,PRIMARY KEY(lineage,sequence));
CREATE TABLE portable_history(lineage TEXT PRIMARY KEY,sequence INTEGER NOT NULL,checked_at TEXT NOT NULL);
CREATE TABLE portable_capabilities(capability TEXT NOT NULL,subject TEXT NOT NULL,authorized_by TEXT,authorized_at TEXT,PRIMARY KEY(capability,subject));
CREATE TABLE portable_sessions(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,state TEXT NOT NULL,parts INTEGER NOT NULL DEFAULT 0,bytes INTEGER NOT NULL DEFAULT 0,header TEXT,result TEXT,error TEXT);
CREATE TABLE portable_parts(session_id TEXT NOT NULL REFERENCES portable_sessions(id) ON DELETE CASCADE,ordinal INTEGER NOT NULL,object_key TEXT NOT NULL UNIQUE,size INTEGER NOT NULL,sha256 TEXT NOT NULL,PRIMARY KEY(session_id,ordinal));
CREATE TABLE portable_files(session_id TEXT NOT NULL REFERENCES portable_sessions(id) ON DELETE CASCADE,ordinal INTEGER NOT NULL,object_key TEXT NOT NULL,size INTEGER NOT NULL,sha256 TEXT NOT NULL,available INTEGER NOT NULL,reason TEXT,staged_key TEXT,upload_id TEXT,written INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(session_id,ordinal),UNIQUE(session_id,object_key));
