-- Import erasures are the currently implemented erasure source. Full entity erasure
-- appends the same lineage journal in its own deletion transaction.
CREATE TRIGGER portable_import_erasure AFTER INSERT ON ik_d1_erasure_journal WHEN NOT EXISTS(SELECT 1 FROM custody_admission) BEGIN
 INSERT INTO portable_journal(lineage,sequence,recorded_at,receipt) SELECT lineage,COALESCE((SELECT MAX(sequence) FROM portable_journal WHERE lineage=portable_state.lineage),0)+1,NEW.recorded_at,NEW.id FROM portable_state WHERE singleton=1;
END;
CREATE TABLE portable_journal_stage(session_id TEXT NOT NULL REFERENCES portable_sessions(id) ON DELETE CASCADE,lineage TEXT NOT NULL,sequence INTEGER NOT NULL,recorded_at TEXT NOT NULL,receipt TEXT NOT NULL,PRIMARY KEY(session_id,lineage,sequence));
CREATE TRIGGER portable_journal_generation AFTER INSERT ON portable_journal BEGIN UPDATE portable_state SET generation=generation+1 WHERE singleton=1; END;
